import * as THREE from 'three/webgpu';
import { texture, uv, vec2, mix, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const atlasRect = { x: 0, y: 0, w: 512, h: 320 };
  const atlasSize = { w: 512, h: 320 };

  const aspect = atlasRect.w / atlasRect.h;
  const height = 1.6;
  const width = height * aspect;

  const geometry = new THREE.PlaneGeometry(width, height);

  const tex = ctx.textureLoader.load('/prism-mock/home/nodes/floating-accent.png');
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = THREE.ClampToEdgeWrapping;
  tex.wrapT = THREE.ClampToEdgeWrapping;

  const offsetX = atlasRect.x / atlasSize.w;
  const offsetY = atlasRect.y / atlasSize.h;
  const scaleX = atlasRect.w / atlasSize.w;
  const scaleY = atlasRect.h / atlasSize.h;

  const uvNode = uv().mul(vec2(scaleX, scaleY)).add(vec2(offsetX, offsetY));
  const grain = uniform(0.03);

  const material = new THREE.MeshBasicNodeMaterial();
  material.map = tex;
  material.colorNode = texture(tex, uvNode);
  material.transparent = true;
  material.opacity = 1.0;
  material.toneMapped = false;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(-3.2, -0.3, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  const group = new THREE.Group();
  group.name = 'pricing-card-1-accent';
  group.add(mesh);
  group.position.copy(mesh.position);
  mesh.position.set(0, 0, 0);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (tex && tex.dispose) tex.dispose();
  };

  return group;
}
